{"hypotheses": [
  {"name": "Hypothesis 1", 
   "mechanism": "Firms with higher operational leverage and low accruals are likely to have more stable cash flows, making them less sensitive to business cycles. The impact is more pronounced during high VIX periods.", 
   "expression": {
     "terms": [
       {"weight": 1.0, "primitive": "OPLeverage"}, 
       {"weight": -1.0, "primitive": "AbnormalAccruals"}
     ], 
     "regime": "VIX_ABOVE_TRAILING_MEDIAN", 
     "vol_target": true
   }, 
   "auxiliary_predictions": [
     {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
     {"type": "size_segment", "segment": "large", "direction": "stronger"},
     {"type": "correlation", "primitive": "Beta", "bound": "below", "threshold": 0.3}
   ], 
   "expected_annualized_sharpe": 0.7, 
   "expected_decay_half_life_months": 36},
  {"name": "Hypothesis 2", 
   "mechanism": "Companies with high growth in advertising expenses and low cash/assets ratio may be sacrificing short-term profitability for visibility and future growth, this effect is stronger when market is up.", 
   "expression": {
     "terms": [
       {"weight": 1.0, "primitive": "GrAdExp"}, 
       {"weight": -0.5, "primitive": "Cash"}
     ], 
     "regime": "MKT_TRAILING_12M_UP", 
     "vol_target": false
   }, 
   "auxiliary_predictions": [
     {"type": "size_segment", "segment": "small", "direction": "stronger"},
     {"type": "international", "region": "emerging", "direction": "same_sign"},
     {"type": "subperiod_consistency"}
   ], 
   "expected_annualized_sharpe": 0.6, 
   "expected_decay_half_life_months": 48},
  {"name": "Hypothesis 3", 
   "mechanism": "Firms with higher share issuance and larger asset growth tend to underperform due to dilution and overinvestment, especially in negative term spread environment.", 
   "expression": {
     "terms": [
       {"weight": -1.0, "primitive": "ShareIss1Y"}, 
       {"weight": -1.0, "primitive": "AssetGrowth"}
     ], 
     "regime": "TERM_SPREAD_NEGATIVE", 
     "vol_target": true
   }, 
   "auxiliary_predictions": [
     {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
     {"type": "size_segment", "segment": "mega", "direction": "stronger"},
     {"type": "correlation", "primitive": "BM", "bound": "above", "threshold": 0.3}
   ], 
   "expected_annualized_sharpe": 0.8, 
   "expected_decay_half_life_months": 60},
  {"name": "Hypothesis 4", 
   "mechanism": "Firms with high operating profitability and low idiosyncratic risk are less likely to experience financial distress, resulting in higher returns, especially when market is down.", 
   "expression": {
     "terms": [
       {"weight": 1.0, "primitive": "OperProf"}, 
       {"weight": -0.5, "primitive": "IdioVol3F"}
     ], 
     "regime": "MKT_TRAILING_12M_DOWN", 
     "vol_target": false
   }, 
   "auxiliary_predictions": [
     {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
     {"type": "size_segment", "segment": "large", "direction": "stronger"},
     {"type": "correlation", "primitive": "Beta", "bound": "below", "threshold": 0.3}
   ], 
   "expected_annualized_sharpe": 0.9, 
   "expected_decay_half_life_months": null},
  {"name": "Hypothesis 5", 
   "mechanism": "Firms with high governance index and low intangible return using EP are likely to have stronger corporate discipline and less speculative growth, leading to higher returns.", 
   "expression": {
     "terms": [
       {"weight": 1.0, "primitive": "Governance"}, 
       {"weight": -1.0, "primitive": "IntanEP"}
     ], 
     "regime": null, 
     "vol_target": true
   }, 
   "auxiliary_predictions": [
     {"type": "size_segment", "segment": "mega", "direction": "stronger"},
     {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
     {"type": "correlation", "primitive": "Size", "bound": "above", "threshold": 0.3}
   ], 
   "expected_annualized_sharpe": 0.75, 
   "expected_decay_half_life_months": 24},
  {"name": "Hypothesis 6", 
   "mechanism": "Firms with high inventory and sales growth relative to overhead growth tend to outperform, especially in positive term spread environment.", 
   "expression": {
     "terms": [
       {"weight": 1.0, "primitive": "InvGrowth"}, 
       {"weight": 0.5, "primitive": "GrSaleToGrOverhead"}
     ], 
     "regime": "TERM_SPREAD_POSITIVE", 
     "vol_target": false
   }, 
   "auxiliary_predictions": [
     {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
     {"type": "size_segment", "segment": "small", "direction": "stronger"},
     {"type": "subperiod_consistency"}
   ], 
   "expected_annualized_sharpe": 0.85, 
   "expected_decay_half_life_months": 36},
  {"name": "Hypothesis 7", 
   "mechanism": "Companies with high short-term reversal and low tangible assets might exhibit strong mean-reversion patterns in returns due to overreaction in the market, particularly effective in developed markets outside the US.", 
   "expression": {
     "terms": [
       {"weight": 1.0, "primitive": "STreversal"}, 
       {"weight": -0.5, "primitive": "tang"}
     ], 
     "regime": null, 
     "vol_target": true
   }, 
   "auxiliary_predictions": [
     {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
     {"type": "size_segment", "segment": "micro", "direction": "stronger"},
     {"type": "correlation", "primitive": "Mom12m", "bound": "below", "threshold": 0.3}
   ], 
   "expected_annualized_sharpe": 0.65, 
   "expected_decay_half_life_months": 48},
  {"name": "Hypothesis 8", 
   "mechanism": "Firms with low R&D capital-to-assets and high debt issuance tend to underperform due to overleverage and lack of innovation, particularly during market downturns.", 
   "expression": {
     "terms": [
       {"weight": -1.0, "primitive": "RDcap"}, 
       {"weight": -1.0, "primitive": "DebtIssuance"}
     ], 
     "regime": "MKT_TRAILING_12M_DOWN", 
     "vol_target": false
   }, 
   "auxiliary_predictions": [
     {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
     {"type": "size_segment", "segment": "large", "direction": "stronger"},
     {"type": "correlation", "primitive": "Beta", "bound": "above", "threshold": 0.3}
   ], 
   "expected_annualized_sharpe": 0.8, 
   "expected_decay_half_life_months": 60}
]}
